<?php
declare(strict_types=1);

/*
 * Arquivo único para Hostinger.
 * Se ?api=pix for chamado, gera o PIX pela AmploPay.
 * Caso contrário, exibe a página.
 */

const AMPLOPAY_PUBLIC_KEY = 'resendeclaraana_kbw0o0cog22g9ibc';
const AMPLOPAY_SECRET_KEY = 'gpwl245gqoz3k739dl6v9wgr3cj2v17g03luc3lts0i50mm6h56fopdc05ipnu1d';
const AMPLOPAY_PIX_ENDPOINT = 'https://app.amplopay.com/api/v1/gateway/pix/receive';

function send_json(int $status, array $payload): never {
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    echo json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

if (($_GET['api'] ?? '') === 'pix') {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
        send_json(405, ['ok' => false, 'message' => 'Método não permitido.']);
    }

    if (!function_exists('curl_init')) {
        send_json(500, ['ok' => false, 'message' => 'cURL não está disponível no servidor.']);
    }

    $raw = file_get_contents('php://input');
    $input = json_decode($raw ?: '', true);

    if (!is_array($input)) {
        send_json(400, ['ok' => false, 'message' => 'Dados inválidos.']);
    }

    $allowed = [10.0, 30.0, 50.0, 75.0, 100.0, 150.0, 200.0, 300.0, 500.0, 1000.0];
    $amount = (float)($input['amount'] ?? 0);
    $name = trim((string)($input['name'] ?? ''));
    $email = trim((string)($input['email'] ?? ''));
    $phone = trim((string)($input['phone'] ?? ''));
    $document = trim((string)($input['document'] ?? ''));

    $phoneDigits = preg_replace('/\D+/', '', $phone);
    $documentDigits = preg_replace('/\D+/', '', $document);

    if (strlen($phoneDigits) !== 10 && strlen($phoneDigits) !== 11) {
        send_json(400, ['ok' => false, 'message' => 'Informe um telefone válido com DDD.']);
    }

    if (strlen($documentDigits) !== 11) {
        send_json(400, ['ok' => false, 'message' => 'Informe um CPF válido com 11 dígitos.']);
    }

    if (strlen($phoneDigits) === 11) {
        $phone = '(' . substr($phoneDigits, 0, 2) . ') ' .
                 substr($phoneDigits, 2, 5) . '-' .
                 substr($phoneDigits, 7, 4);
    } else {
        $phone = '(' . substr($phoneDigits, 0, 2) . ') ' .
                 substr($phoneDigits, 2, 4) . '-' .
                 substr($phoneDigits, 6, 4);
    }

    $document = substr($documentDigits, 0, 3) . '.' .
                substr($documentDigits, 3, 3) . '.' .
                substr($documentDigits, 6, 3) . '-' .
                substr($documentDigits, 9, 2);

    $validAmount = false;
    foreach ($allowed as $v) {
        if (abs($amount - $v) < 0.001) {
            $validAmount = true;
            break;
        }
    }

    if (!$validAmount) {
        send_json(400, ['ok' => false, 'message' => 'Valor inválido.']);
    }
    if (mb_strlen($name) < 2) {
        send_json(400, ['ok' => false, 'message' => 'Informe seu nome.']);
    }
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        send_json(400, ['ok' => false, 'message' => 'Informe um e-mail válido.']);
    }

    try {
        $identifier = 'doacao_' . gmdate('YmdHis') . '_' . bin2hex(random_bytes(6));
    } catch (Throwable $e) {
        $identifier = 'doacao_' . str_replace('.', '', uniqid('', true));
    }

    $client = [
        'name' => $name,
        'email' => $email,
        'phone' => $phone,
        'document' => $document
    ];

    $dueDate = new DateTime('now', new DateTimeZone('America/Sao_Paulo'));
    $dueDate->modify('+2 days');

    $productId = 'contribuicao_' . str_replace('.', '_', number_format($amount, 2, '.', ''));

    /*
     * Mantém a soma dos itens exatamente igual ao amount, conforme o exemplo
     * da documentação da AmploPay.
     */
    $payload = [
        'identifier' => $identifier,
        'amount' => $amount,
        'shippingFee' => 0,
        'extraFee' => 0,
        'discount' => 0,
        'client' => $client,
        'products' => [
            [
                'id' => $productId,
                'name' => 'Contribuição',
                'quantity' => 1,
                'price' => $amount
            ]
        ],
        'dueDate' => $dueDate->format('Y-m-d'),
        'metadata' => [
            'source' => 'pagina-doacao-hostinger',
            'identifier' => $identifier
        ]
    ];

    $ch = curl_init(AMPLOPAY_PIX_ENDPOINT);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST => true,
        CURLOPT_CONNECTTIMEOUT => 10,
        CURLOPT_TIMEOUT => 30,
        CURLOPT_HTTPHEADER => [
            'Accept: application/json',
            'Content-Type: application/json',
            'x-public-key: ' . AMPLOPAY_PUBLIC_KEY,
            'x-secret-key: ' . AMPLOPAY_SECRET_KEY
        ],
        CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)
    ]);

    $body = curl_exec($ch);
    $curlError = curl_error($ch);
    $statusCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($body === false || $body === '') {
        send_json(502, [
            'ok' => false,
            'message' => 'Não foi possível obter resposta da AmploPay.',
            'details' => $curlError ?: null
        ]);
    }

    $data = json_decode($body, true);

    if (!is_array($data)) {
        send_json(502, [
            'ok' => false,
            'message' => 'A AmploPay retornou uma resposta inválida.'
        ]);
    }

    if ($statusCode < 200 || $statusCode >= 300) {
        send_json(
            ($statusCode >= 400 && $statusCode < 500) ? 400 : 502,
            [
                'ok' => false,
                'message' => $data['message'] ?? $data['errorDescription'] ?? 'A AmploPay recusou a criação do PIX.',
                'errorCode' => $data['errorCode'] ?? null,
                'details' => $data['details'] ?? null
            ]
        );
    }

    $pix = is_array($data['pix'] ?? null) ? $data['pix'] : [];
    $code = (string)($pix['code'] ?? '');

    if ($code === '') {
        send_json(502, [
            'ok' => false,
            'message' => 'A AmploPay não retornou o PIX Copia e Cola.',
            'transactionId' => $data['transactionId'] ?? null
        ]);
    }

    send_json(200, [
        'ok' => true,
        'transactionId' => $data['transactionId'] ?? null,
        'code' => $code,
        'image' => (string)($pix['image'] ?? ''),
        'expiresAt' => (string)($pix['expiresAt'] ?? '')
    ]);
}
