<script>
(function () {
  'use strict';

  var valorSelecionado = 0;
  var transactionIdAtual = null;
  var pollingTimer = null;

  var modal = document.getElementById('modal-pagamento');
  var valorEl = document.getElementById('valor-doacao');
  var etapaDados = document.getElementById('etapa-dados');
  var etapaPix = document.getElementById('etapa-pix');
  var erroEl = document.getElementById('erro-pix');
  var btnGerar = document.getElementById('btn-gerar-pix');
  var campoPix = document.getElementById('campo-codigo-pix');
  var areaQr = document.getElementById('area-qr-code');
  var expiraEl = document.getElementById('pix-expira');

  function moeda(v) {
    return Number(v).toLocaleString('pt-BR', {
      style: 'currency',
      currency: 'BRL'
    });
  }

  function mostrarErro(msg) {
    erroEl.textContent = msg;
    erroEl.style.display = 'block';
  }

  function limparErro() {
    erroEl.textContent = '';
    erroEl.style.display = 'none';
  }

  function abrirModal(valor) {
    valorSelecionado = Number(valor);
    valorEl.textContent = moeda(valorSelecionado);

    limparErro();
    etapaDados.style.display = 'block';
    etapaPix.style.display = 'none';
    campoPix.value = '';
    areaQr.innerHTML = '';
    expiraEl.textContent = '';

    document.getElementById('tela-pix').style.display = 'block';
    document.getElementById('tela-confirmacao').style.display = 'none';
    pararPolling();
    transactionIdAtual = null;
    modal.style.display = 'flex';
    modal.setAttribute('aria-hidden', 'false');
  }

  function fecharModal() {
    pararPolling();
    modal.style.display = 'none';
    modal.setAttribute('aria-hidden', 'true');
  }

  document.querySelectorAll('.btn-doacao').forEach(function (botao) {
    botao.addEventListener('click', function () {
      abrirModal(botao.getAttribute('data-value'));
    });
  });

  var fechar = document.getElementById('btn-fechar');
  if (fechar) fechar.addEventListener('click', fecharModal);

  var fundo = document.querySelector('.fundo-modal');
  if (fundo) fundo.addEventListener('click', fecharModal);

  function pararPolling() {
    if (pollingTimer) {
      clearInterval(pollingTimer);
      pollingTimer = null;
    }
  }

  async function consultarPagamento() {
    if (!transactionIdAtual) return;
    try {
      var r = await fetch('api/amplopay/consultar-status.php?id=' + encodeURIComponent(transactionIdAtual), {
        method: 'GET',
        cache: 'no-store'
      });
      var d = await r.json();
      if (!r.ok || !d.ok) return;

      if (d.paid || d.event === 'TRANSACTION_PAID' || d.transactionStatus === 'COMPLETED') {
        pararPolling();
        document.getElementById('tela-pix').style.display = 'none';
        document.getElementById('tela-confirmacao').style.display = 'block';
      } else if (['TRANSACTION_CANCELED','TRANSACTION_REFUNDED','TRANSACTION_CHARGED_BACK'].includes(d.event)) {
        pararPolling();
        var statusEl = document.getElementById('status-doacao');
        if (statusEl) statusEl.textContent = 'Esta cobrança não está mais disponível. Gere um novo PIX.';
      }
    } catch (e) {
      // Falhas temporárias de consulta não interrompem o pagamento.
    }
  }

  function iniciarPolling(id) {
    // Confirmação automática será adicionada quando o endpoint de consulta
    // estiver configurado nesta versão de arquivo único.
    return;
  }

  btnGerar.addEventListener('click', async function () {
    limparErro();

    var name = document.getElementById('doador-nome').value.trim();
    var email = document.getElementById('doador-email').value.trim();
    var phone = document.getElementById('doador-phone').value.trim();
    var documentNumber = document.getElementById('doador-document').value.trim();

    if (!name || name.length < 2) {
      mostrarErro('Informe seu nome.');
      return;
    }

    if (!email || !email.includes('@')) {
      mostrarErro('Informe um e-mail válido.');
      return;
    }

    var phoneDigits = phone.replace(/\D/g, '');
    var documentDigits = documentNumber.replace(/\D/g, '');

    if (phoneDigits.length !== 10 && phoneDigits.length !== 11) {
      mostrarErro('Informe um telefone válido com DDD.');
      return;
    }

    if (documentDigits.length !== 11) {
      mostrarErro('Informe um CPF válido com 11 dígitos.');
      return;
    }

    if (typeof fbq === 'function') {
      fbq('track', 'InitiateCheckout', {
        value: Number(valorSelecionado),
        currency: 'BRL'
      });
    }

    btnGerar.disabled = true;
    btnGerar.textContent = 'GERANDO PIX...';

    try {
      var response = await fetch('?api=pix', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
          amount: valorSelecionado,
          name: name,
          email: email,
          phone: phone,
          document: documentNumber
        })
      });

      var rawResponse = await response.text();
      if (!rawResponse || !rawResponse.trim()) {
        throw new Error('O servidor respondeu sem conteúdo.');
      }
      var data;
      try {
        data = JSON.parse(rawResponse);
      } catch (e) {
        throw new Error('O servidor retornou uma resposta inválida.');
      }

      if (!response.ok || !data.ok) {
        var mensagem = data.message || 'Não foi possível gerar o PIX.';

        if (Array.isArray(data.details) && data.details.length) {
          var detalhes = data.details.map(function(item) {
            if (!item) return '';

            var caminho = item.path ? String(item.path) : '';
            var erro = item.error;

            var descricao = '';
            if (typeof erro === 'string') {
              descricao = erro;
            } else if (erro && typeof erro === 'object') {
              descricao =
                erro.message ||
                erro.description ||
                erro.error ||
                JSON.stringify(erro);
            }

            if (!descricao && item.message) {
              descricao = String(item.message);
            }

            if (!descricao) {
              descricao = JSON.stringify(item);
            }

            return (caminho ? caminho + ': ' : '') + descricao;
          }).filter(Boolean);

          if (detalhes.length) {
            mensagem += ' — ' + detalhes.join(' | ');
          }
        }

        if (data.errorCode) {
          mensagem += ' [' + data.errorCode + ']';
        }

        throw new Error(mensagem);
      }

      campoPix.value = data.code || '';

      areaQr.innerHTML = '';
      if (data.image) {
        var img = document.createElement('img');
        img.src = data.image;
        img.alt = 'QR Code PIX';
        areaQr.appendChild(img);
      } else {
        areaQr.textContent = 'Use o código PIX Copia e Cola abaixo.';
      }

      if (data.expiresAt) {
        var d = new Date(data.expiresAt);
        expiraEl.textContent = isNaN(d.getTime())
          ? 'Validade: ' + data.expiresAt
          : 'Este PIX expira em ' + d.toLocaleString('pt-BR') + '.';
      }

      etapaDados.style.display = 'none';
      etapaPix.style.display = 'block';

    } catch (e) {
      mostrarErro(e.message || 'Erro inesperado ao gerar o PIX.');
    } finally {
      btnGerar.disabled = false;
      btnGerar.textContent = 'GERAR PIX';
    }
  });

  var copiar = document.getElementById('btn-copiar-pix');
  copiar.addEventListener('click', async function () {
    if (!campoPix.value) return;

    try {
      await navigator.clipboard.writeText(campoPix.value);
    } catch (e) {
      campoPix.select();
      document.execCommand('copy');
    }

    var antigo = copiar.textContent;
    copiar.textContent = 'COPIADO!';
    setTimeout(function () {
      copiar.textContent = antigo;
    }, 1400);
  });

  document.querySelectorAll('.pergunta-q').forEach(function (q) {
    q.addEventListener('click', function () {
      this.classList.toggle('aberta');
      this.nextElementSibling.classList.toggle('aberta');
    });
  });

  var ancora = document.getElementById('ancora-doacao');
  if (ancora) {
    ancora.addEventListener('click', function (e) {
      e.preventDefault();
      document.getElementById('doacao').scrollIntoView({behavior: 'smooth'});
    });
  }

  var phoneInput = document.getElementById('doador-phone');
  var docInput = document.getElementById('doador-document');

  if (phoneInput) {
    phoneInput.addEventListener('input', function () {
      var v = this.value.replace(/\D/g, '').slice(0, 11);
      if (v.length > 10) {
        this.value = v.replace(/^(\d{2})(\d{5})(\d{0,4}).*/, '($1) $2-$3');
      } else if (v.length > 6) {
        this.value = v.replace(/^(\d{2})(\d{4})(\d{0,4}).*/, '($1) $2-$3');
      } else if (v.length > 2) {
        this.value = v.replace(/^(\d{2})(\d*)/, '($1) $2');
      } else {
        this.value = v;
      }
    });
  }

  if (docInput) {
    docInput.addEventListener('input', function () {
      var v = this.value.replace(/\D/g, '').slice(0, 11);
      this.value = v
        .replace(/^(\d{3})(\d)/, '$1.$2')
        .replace(/^(\d{3})\.(\d{3})(\d)/, '$1.$2.$3')
        .replace(/\.(\d{3})(\d)/, '.$1-$2');
    });
  }

})();
</script>

</body>
</html>
